 labels=pd.concat(label_rows,ignore_index=True); labels.to_csv(OUT/'p3_dual_model_exact_label_contract.csv.gz',index=False,compression='gzip',encoding='utf-8')
 # Frozen feature matrix contains no outcome columns. Missing indicators are explicit.
