 for c in frozen:
  if c not in x: x[c]=np.nan
  if x[c].dtype.kind in 'biufc': x[f'{c}__missing']=x[c].isna()
 x[['decision_date','ticker','raw_state','selected_eligibility','P3_segment','full_spec_v2_state','controller_state_status',*frozen,*[f'{c}__missing' for c in frozen if f'{c}__missing' in x]]].to_csv(OUT/'p3_dual_model_frozen_feature_matrix.csv.gz',index=False,compression='gzip',encoding='utf-8')
 dictionary=[]
